-- An `UPDATE` that writes an oversized key meets the same refusal as an `INSERT`.
-- @setup
CREATE TABLE t (id int, a text);
CREATE INDEX t_i ON t (a);
INSERT INTO t VALUES (1, 'short');
-- @test
-- @expect-error: an update to an oversized key
-- @expect-message
-- @profile-lock
UPDATE t SET a = '' WHERE id = 1;
